// Validate comparison input. Components built deterministically below; LLM never ranks.
const i = $input.first().json;
if (!i.procurement_id) throw new Error('Missing procurement_id');
if (!i.weights || typeof i.weights !== 'object') throw new Error('Missing weights config');
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, currency: i.currency ?? null, budget: i.budget ?? null, products: i.products ?? [], evaluations: i.evaluations ?? [], offers: i.offers ?? [], weights: i.weights } }];

// Build per-candidate components with deterministic normalizers ONLY.
// No price evidence -> price null. Currency mismatch or no price -> budget null. No rating -> reviews/quality null.
const inp = $input.first().json;
const byId = Object.fromEntries(inp.evaluations.map((e) => [e.product_id, e]));
const offersByProduct = {};
for (const o of inp.offers) { (offersByProduct[o.product_id] = offersByProduct[o.product_id] || []).push(o); }
const normRating = (r, s) => (typeof r === 'number' && typeof s === 'number' && s > 0 && r >= 0 && r <= s) ? r / s : null;
const rows = inp.products.map((p) => {
  const ev = byId[p.product_id] || {};
  const offers = offersByProduct[p.product_id] || [];
  const priced = offers.filter((o) => typeof o.net_price === 'number' && o.net_price > 0 && o.currency).map((o) => ({ price: o.net_price, currency: String(o.currency).toUpperCase() }));
  const sameCur = inp.currency ? priced.filter((x) => x.currency === String(inp.currency).toUpperCase()) : [];
  const best = sameCur.length ? Math.min(...sameCur.map((x) => x.price)) : null;
  const comps = {
    price: null, quality: null,
    reviews: normRating(ev.review_rating, ev.review_scale ?? 5),
    delivery: null, warranty: null, vendor_reliability: null, payment_terms: null,
    budget_compliance: (best !== null && typeof inp.budget === 'number' && inp.budget > 0) ? (best <= inp.budget ? 1 : 0) : null,
    source_quality: typeof ev.source_quality_score === 'number' ? ev.source_quality_score : null,
    specification_completeness: typeof ev.specification_completeness === 'number' ? ev.specification_completeness : null,
  };
  if (comps.reviews !== null) comps.quality = comps.reviews;
  const strengths = [], limitations = [];
  if (ev.source_quality === 'HIGH') strengths.push('High-quality evidence source (' + (p.source_url || '') + ')');
  else if (ev.source_quality) limitations.push('Source quality is ' + ev.source_quality + ' — treat as candidate, not verified product');
  if ((ev.spec_fields_verified ?? 0) > 0) strengths.push(ev.spec_fields_verified + '/' + (ev.spec_fields_total ?? '?') + ' defined specifications verified');
  else limitations.push('No defined specifications verifiable from source');
  if (comps.reviews !== null) strengths.push('Verified review rating ' + ev.review_rating + '/' + (ev.review_scale ?? 5));
  else limitations.push('Review data unavailable');
  if (best === null) limitations.push(inp.currency && priced.length ? 'Price evidence exists but currency mismatch — no conversion without FX source' : 'Price comparison unavailable');
  else if (comps.budget_compliance === 1) strengths.push('Best verified price within budget');
  else limitations.push('Best verified price exceeds budget');
  return { product_id: p.product_id, components: comps, strengths, limitations, evidence_urls: ev.source_urls ?? [p.source_url].filter(Boolean), confidence: p.confidence ?? 0 };
});
  return rows.map((r) => ({ json: { product_id: r.product_id, components: r.components, weights: inp.weights, _meta: { strengths: r.strengths, limitations: r.limitations, evidence_urls: r.evidence_urls, confidence: r.confidence } } }));

// Merge per-row engine scores with row metadata (joined on product_id, never position),
// then rank deterministically (score desc, nulls last, confidence desc, product_id asc).
const scored = $input.all().map((i) => i.json);
const meta = {};
for (const m of $('Build Components').all().map((i) => i.json)) { meta[m.product_id] = m._meta; }
const merged = scored.map((s) => {
  const m = meta[s.product_id] || { strengths: [], limitations: ['Row metadata unavailable'], evidence_urls: [], confidence: 0 };
  return { product_id: s.product_id, overall_score: (typeof s.overall_score === 'number' ? s.overall_score : null), criteria_used: s.criteria_used ?? [], criteria_missing: s.criteria_missing ?? [], effective_weight_total: s.effective_weight_total ?? 0, criteria_scores: s.breakdown ?? {}, strengths: m.strengths, limitations: m.limitations, evidence_urls: m.evidence_urls, confidence: m.confidence };
});
merged.sort((a, b) => {
  if (a.overall_score === null && b.overall_score === null) {}
  else if (a.overall_score === null) return 1;
  else if (b.overall_score === null) return -1;
  else if (b.overall_score !== a.overall_score) return b.overall_score - a.overall_score;
  if ((b.confidence ?? 0) !== (a.confidence ?? 0)) return (b.confidence ?? 0) - (a.confidence ?? 0);
  return String(a.product_id).localeCompare(String(b.product_id));
});
merged.forEach((m, i) => { m.rank = i + 1; if (!m.evidence_urls.length) throw new Error('missing evidence_urls: ' + m.product_id); });
return [{ json: { procurement_id: $('Validate Input').first().json.procurement_id, comparisons: merged } }];
